// EaserCAT 3000 - four axis CiA402 stepper drive (ETG.6010), modes csp and csv.
//
// Object dictionary, ESI file and EEPROM image are generated by tools/gen_od.py.
//
// Cycle handling:
//  - DC synchronous (SYNC0): the SYNC0 interrupt only sets a flag. The main loop then
//    reads the outputs, runs the CiA402 state machines and the step generators and
//    writes the inputs. All SPI accesses to the ESC are done from the main loop.
//  - SM synchronous (no DC): the same cycle is run every time new outputs (SM2 event)
//    have arrived.
//  - Without process data (INIT/PREOP/SAFEOP without frames) a 1 ms housekeeping
//    cycle keeps the state machines and the stop ramps running.

#include <Arduino.h>
#include <stdio.h>
extern "C" {
#include "ecat_slv.h"
#include "utypes.h"
};
_Objects Obj;

#include "Cia402Axis.h"
#include "ObjectHooks.h"
#include "StepGen3.h"
#include "extend32to64.h"

// Own instance on USART1 (PA10 RX, PA9 TX). Newer STM32duino cores already define DebugSerial.
HardwareSerial DebugSerial(PA10, PA9);

////// Digital IO
const uint32_t INPUTS[8] = {PE8, PE9, PE10, PE11, PE12, PE13, PE14, PE15};
const uint32_t OUTPUTS[4] = {PC5, PB0, PB1, PE7};
const uint32_t DIGITAL_IO_SHIFT = 16;  // Board IO in bits 16.. of 0x60FD / 0x60FE:01

///// Analog out
const uint32_t DAC1_pin = PA4;
const float DAC_FULL_SCALE_V = 3.3f;
const uint32_t DAC_RESOLUTION_BITS = 12;

////// Step generators and CiA402 axes
StepGen3 *Step = nullptr;
Cia402Axis Axes[N_AXES];
HardwareTimer *baseTimer;           // Step pulse base period timer
volatile int32_t pulsesLeft = 0;    // Base periods left before the pulse train stops
uint32_t requestedBasePeriod = 0;   // Last value of 0x2000 applied to the timer
void basePeriodCB(void);

///////// Spindle encoder
#include "MyEncoder.h"
void indexPulseEncoderCB1(void);
MyEncoder Encoder1(TIM2, PA3, indexPulseEncoderCB1);
void indexPulseEncoderCB1(void) { Encoder1.indexPulse(); }
extend32to64 longTime;

////// EtherCAT
const uint32_t SYNC0_PIN = PC3;
volatile bool sync0Pending = false;      // Set by the SYNC0 interrupt
volatile uint32_t lastSync0Micros = 0;
volatile bool sync0Seen = false;         // A SYNC0 has arrived since the interrupt was enabled
volatile uint16_t sync0Overruns = 0;     // SYNC0 arrived before the last cycle was served
// The master sets the SYNC0 start time ahead (IgH: about 100 ms) and may request OP before
// the first pulse. Only a SYNC0 that has not started within this time is an error.
const int32_t SYNC0_START_TIMEOUT_US = 1000000;
uint32_t sync0CycleNs = 0;               // From the ESC when DC is activated
uint32_t lastCycleMicros = 0;
bool commLostPending = false;
bool wasInOp = false;

extern "C" uint32_t ESC_SYNC0cycletime(void);  // SOES, not declared in esc.h
void sync0Handler(void);
void ESC_interrupt_enable(uint32_t mask);
void ESC_interrupt_disable(uint32_t mask);
uint16_t dc_checker(void);
void safeOutputs(void);
void preStateChange(uint8_t *as, uint8_t *an);

static esc_cfg_t config = {
    .user_arg = NULL,
    .use_interrupt = 1,  // Needed: makes SOES check DC and call ESC_interrupt_enable
    .watchdog_cnt = 150,  // Cycles without new outputs before the SM watchdog trips
    .skip_default_initialization = false,
    .set_defaults_hook = NULL,
    .pre_state_change_hook = preStateChange,
    .post_state_change_hook = NULL,
    .application_hook = NULL,  // The application cycle is called explicitly
    .safeoutput_override = safeOutputs,
    .pre_object_download_hook = ObjectHooks_preDownload,
    .post_object_download_hook = NULL,
    .pre_object_upload_hook = NULL,
    .post_object_upload_hook = NULL,
    .rxpdo_override = NULL,
    .txpdo_override = NULL,
    .esc_hw_interrupt_enable = ESC_interrupt_enable,
    .esc_hw_interrupt_disable = ESC_interrupt_disable,
    .esc_hw_eep_handler = NULL,
    .esc_check_dc_handler = dc_checker,
    .get_device_id = NULL,
};

static inline bool inOp(void) { return (ESCvar.ALstatus & 0x0F) == ESCop; }
static inline bool outputsActive(void) {
  return (ESCvar.App.state & APPSTATE_OUTPUT) != 0;
}

////// Base period timer

void setBasePeriod(uint32_t ns) {
  requestedBasePeriod = ns;
  if (ns < BASE_PERIOD_MIN_NS) ns = BASE_PERIOD_MIN_NS;
  if (ns > BASE_PERIOD_MAX_NS) ns = BASE_PERIOD_MAX_NS;
  uint32_t clk = baseTimer->getTimerClkFreq();
  uint32_t ticks = (uint32_t)(((uint64_t)ns * clk) / 1000000000ULL);
  baseTimer->setPrescaleFactor(1);
  baseTimer->setOverflow(ticks, TICK_FORMAT);
  // Use the period actually produced by the timer in the step generator math
  Step->basePeriodNs = (long)(((uint64_t)ticks * 1000000000ULL) / clk);
}

void basePeriodCB(void) {
  if (pulsesLeft > 0) {
    pulsesLeft--;
    Step->makeAllPulses();
  } else {
    baseTimer->pause();
  }
}

// Restart the pulse train in phase with the current cycle
void restartPulseTrain(uint32_t cycleNs) {
  int32_t n = (int32_t)(cycleNs / (uint32_t)Step->basePeriodNs);
  baseTimer->pause();
  Step->makeAllPulses();  // First base period right now
  // Some margin, so a slightly late next cycle does not create a gap. The train always
  // stops by itself if no new cycle arrives.
  pulsesLeft = n - 1 + n / 4 + 2;
  baseTimer->refresh();
  baseTimer->resume();
}

////// SOES callbacks for process data

// Master outputs -> hardware. Called by DIG_process when new outputs have arrived.
void cb_set_outputs(void) {
  uint32_t outs = 0;
  for (int i = 0; i < N_AXES; i++)
    outs |= Obj.Axis[i].DigitalOutputs & Obj.Axis[i].DigitalOutputsMask;
  for (int i = 0; i < 4; i++)
    digitalWrite(OUTPUTS[i], (outs >> (DIGITAL_IO_SHIFT + i)) & 1 ? HIGH : LOW);

  float v = Obj.AnalogOut;
  if (!(v > 0.0f)) v = 0.0f;  // also catches NaN
  if (v > DAC_FULL_SCALE_V) v = DAC_FULL_SCALE_V;
  analogWrite(DAC1_pin,
              (uint32_t)(v / DAC_FULL_SCALE_V * ((1u << DAC_RESOLUTION_BITS) - 1) + 0.5f));

  Encoder1.setLatch(Obj.EncoderOut.IndexLatchEnable);
  Encoder1.setScale(Obj.EncoderOut.Scale);
}

// Hardware -> master inputs. Called by DIG_process before the TxPDO is written.
void cb_get_inputs(void) {
  uint32_t in = 0;
  for (int i = 0; i < 8; i++)
    if (digitalRead(INPUTS[i]) == HIGH) in |= 1u << i;
  for (int i = 0; i < N_AXES; i++) Obj.Axis[i].DigitalInputs = in << DIGITAL_IO_SHIFT;

  Obj.EncoderIn.IndexStatus = Encoder1.indexHappened();
  Obj.EncoderIn.Position = Encoder1.currentPos();
  Obj.EncoderIn.IndexPin = Encoder1.getIndexState();
  Obj.EncoderIn.Velocity = Encoder1.frequency(longTime.extendTime(micros()));
}

// Called by SOES when outputs are stopped (leaving OP, also at start up)
void safeOutputs(void) {
  for (int i = 0; i < 4; i++) digitalWrite(OUTPUTS[i], LOW);
  analogWrite(DAC1_pin, 0);
  if (wasInOp) commLostPending = true;
  wasInOp = false;
}

void preStateChange(uint8_t *as, uint8_t *an) {
  (void)as;
  (void)an;
}

////// Application cycle

void applicationCycle(uint32_t cycleNs, bool outputsValid, bool newOutputs) {
  double dt = cycleNs * 1e-9;

  if (commLostPending) {
    commLostPending = false;
    for (int i = 0; i < N_AXES; i++) Axes[i].communicationLost();
  }

  Step->updatePositions();
  uint8_t errorRegister = 0;
  for (int i = 0; i < N_AXES; i++) {
    stepgen_t &sg = Step->stepgen_array[i];
    MotionFeedback fb = {sg.pos_fb, sg.freq};
    MotionCommand cmd = Axes[i].cycle(fb, dt, outputsValid, newOutputs);
    StepTiming_t &t = Obj.StepTiming[i];
    Step->setTiming(i, t.StepLength, t.StepSpace, t.DirSetup, t.DirHold);
    Step->setChannel(i, cmd.enable, cmd.positionMode, cmd.position, cmd.velocity,
                     cmd.maxVelocity, cmd.maxAccel, cmd.resync);
    if (Axes[i].faulted()) errorRegister |= 0x01;  // generic error

    // 0x60C2 interpolation time period = cycle time (value * 10^index s)
    uint32_t us = cycleNs / 1000;
    if (us % 1000 == 0 && us / 1000 <= 255) {
      Obj.Axis[i].InterpolationTimeValue = us / 1000;
      Obj.Axis[i].InterpolationTimeIndex = -3;
    } else if (us <= 255) {
      Obj.Axis[i].InterpolationTimeValue = us;
      Obj.Axis[i].InterpolationTimeIndex = -6;
    } else {
      Obj.Axis[i].InterpolationTimeValue = us / 100 > 255 ? 255 : us / 100;
      Obj.Axis[i].InterpolationTimeIndex = -4;
    }
  }
  Obj.ErrorRegister = errorRegister;

  if (Obj.BasePeriod != requestedBasePeriod) setBasePeriod(Obj.BasePeriod);
  Step->updateFrequencies(cycleNs);
  restartPulseTrain(cycleNs);
}

// One complete process data cycle. fromSync: triggered by SYNC0.
void serveCycle(uint32_t cycleNs, bool fromSync) {
  uint32_t t0 = micros();
  uint32_t ev = ESC_ALeventread();  // also refreshes ESCvar.ALevent
  bool newOutputs = (ev & ESCREG_ALEVENT_SM2) != 0;

  DIG_process(DIG_PROCESS_WD_FLAG | DIG_PROCESS_OUTPUTS_FLAG);
  bool outputsValid = outputsActive();
  if (outputsValid) wasInOp = true;

  if (fromSync && outputsValid) {
    if (!newOutputs) Obj.SmOutParam.SmEventMissed++;
    Obj.SmOutParam.SyncError = newOutputs ? 0 : 1;
    Obj.SmInParam.SmEventMissed = Obj.SmOutParam.SmEventMissed;
    Obj.SmInParam.SyncError = Obj.SmOutParam.SyncError;
  }

  applicationCycle(cycleNs, outputsValid, newOutputs);
  DIG_process(DIG_PROCESS_INPUTS_FLAG);

  // ETG.1020 0x1C32:06 / 0x1C33:06, measured worst case
  uint32_t calcNs = (micros() - t0) * 1000;
  if (calcNs > Obj.SmOutParam.CalcCopyTime) {
    Obj.SmOutParam.CalcCopyTime = calcNs;
    Obj.SmInParam.CalcCopyTime = calcNs;
  }
  Obj.SmOutParam.CycleTimeTooSmall = sync0Overruns;
  Obj.SmInParam.CycleTimeTooSmall = sync0Overruns;
  lastCycleMicros = t0;
}

void setup(void) {
  DebugSerial.begin(115200);
  delay(100);

  for (int i = 0; i < 4; i++) {
    pinMode(OUTPUTS[i], OUTPUT);
    digitalWrite(OUTPUTS[i], LOW);
  }
  for (int i = 0; i < 8; i++) pinMode(INPUTS[i], INPUT);
  pinMode(DAC1_pin, OUTPUT);
  analogWriteResolution(DAC_RESOLUTION_BITS);
  analogWrite(DAC1_pin, 0);

  encoder_config();  // Must be done before the step outputs are configured

  Step = new StepGen3;
  for (int i = 0; i < N_AXES; i++) {
    pinMode(Step->stepPin[i], OUTPUT);
    pinMode(Step->dirPin[i], OUTPUT);
  }

  baseTimer = new HardwareTimer(TIM11);
  baseTimer->attachInterrupt(basePeriodCB);
  setBasePeriod(BASE_PERIOD);

  ecat_slv_init(&config);  // Also sets the object dictionary default values

  for (int i = 0; i < N_AXES; i++) Axes[i].init(&Obj.Axis[i]);
  setBasePeriod(Obj.BasePeriod);
  Obj.SmOutParam.SyncType = 1;  // SM synchronous until DC is activated
  Obj.SmInParam.SyncType = 0x22;
  lastCycleMicros = micros();
  DebugSerial.println("EaserCAT 3000 CiA402 started");
}

void loop(void) {
  if (sync0Pending) {
    sync0Pending = false;
    serveCycle(sync0CycleNs, true);
    ecat_slv_poll();  // Mailbox and state machine, right after the cycle
    return;
  }

  // Read lastSync0Micros before micros(): the SYNC0 interrupt can update it at any time,
  // and a value newer than 'now' would wrap the difference and look like a lost SYNC0.
  uint32_t lastSync0 = lastSync0Micros;
  bool seen = sync0Seen;
  uint32_t now = micros();
  bool dcActive = ESCvar.dcsync && sync0CycleNs != 0;
  int32_t sinceSync0 = (int32_t)(now - lastSync0);  // since the last SYNC0, or since enabling
  bool dcRunning = dcActive && seen &&
                   sinceSync0 < (int32_t)(3 * (sync0CycleNs / 1000) + 2000);
  if (dcRunning) return;  // Wait for SYNC0, don't disturb it with SPI traffic

  // Before the first SYNC0 the loop polls as usual, so the mailbox and the state machine
  // keep running while the master waits for the SYNC0 start time.
  bool sync0Lost = dcActive && (seen || sinceSync0 >= SYNC0_START_TIMEOUT_US);
  if (sync0Lost && inOp()) {
    // DC was activated but SYNC0 stopped, or never started: synchronization error (ETG.1020)
    Obj.SmOutParam.SyncError = Obj.SmInParam.SyncError = 1;
    ESC_ALstatusgotoerror((ESCsafeop | ESCerror), ALERR_SYNCERROR);
  }

  ecat_slv_poll();
  bool smEvent = (ESCvar.ALevent & ESCREG_ALEVENT_SM2) != 0;
  if (!ESCvar.dcsync) {
    Obj.SmOutParam.SyncType = 1;  // SM synchronous
    Obj.SmInParam.SyncType = 0x22;
  }
  // Housekeeping interval: 1 ms, but in OP wait a bit longer for a late frame
  uint32_t housekeepingUs = outputsActive() ? 2000 : 1000;
  if (!ESCvar.dcsync && smEvent) {
    // SM synchronous: one cycle per received frame
    uint32_t dtNs = (now - lastCycleMicros) * 1000;
    if (dtNs < 100000) dtNs = 100000;
    if (dtNs > 10000000) dtNs = 10000000;
    Obj.SmOutParam.CycleTime = Obj.SmInParam.CycleTime = dtNs;
    serveCycle(dtNs, false);
  } else if (now - lastCycleMicros >= housekeepingUs) {
    serveCycle(housekeepingUs * 1000, false);  // Housekeeping cycle without new outputs
  }
}

////// Interrupts and DC

void sync0Handler(void) {
  // No SPI access here, it would collide with an SPI transfer of the main loop.
  if (sync0Pending) sync0Overruns++;
  lastSync0Micros = micros();
  sync0Seen = true;
  sync0Pending = true;
}

void ESC_interrupt_enable(uint32_t mask) {
  if (mask & ESCREG_ALEVENT_DC_SYNC0) {
    sync0Seen = false;
    lastSync0Micros = micros();  // SYNC0_START_TIMEOUT_US counts from here
    attachInterrupt(digitalPinToInterrupt(SYNC0_PIN), sync0Handler, RISING);
  }
}

void ESC_interrupt_disable(uint32_t mask) {
  if (mask & ESCREG_ALEVENT_DC_SYNC0) {
    detachInterrupt(digitalPinToInterrupt(SYNC0_PIN));
    sync0Pending = false;
    sync0Seen = false;
  }
}

// Called by SOES at PREOP->SAFEOP when the master has activated the SYNC unit
uint16_t dc_checker(void) {
  uint32_t cycle = ESC_SYNC0cycletime();  // ns
  uint32_t minCycle = 250000;             // 0x1C32:05
  if (cycle < minCycle || cycle > 100000000 || cycle < 2 * (uint32_t)Step->basePeriodNs)
    return ALERR_DCSYNC0CYCLETIME;
  sync0CycleNs = cycle;
  ESCvar.dcsync = 1;
  Obj.SmOutParam.SyncType = 2;  // DC SYNC0
  Obj.SmInParam.SyncType = 2;
  Obj.SmOutParam.CycleTime = Obj.SmInParam.CycleTime = cycle;
  return 0;
}
